"""Write and read the SQL dumps generated by the backup tools.

Dumps are written with MySQL/MariaDB escaping (backslashes, quotes, NUL,
newlines and ^Z escaped), so each value fits on one line and round-trips
exactly under the default SQL mode. Reading uses a quote-aware splitter, so a
``;`` or newline inside a value never ends a statement; older dumps that stored
raw newlines restore correctly too.
"""

import re
from datetime import date, datetime, time, timedelta
from decimal import Decimal


INSERT_START = re.compile(r'^INSERT\s+INTO\s+', re.IGNORECASE)
LEGACY_USER_INSERT = re.compile(r'^(INSERT\s+INTO\s+`users`)(\s+VALUES\b)', re.IGNORECASE)
USER_DEFINITION = re.compile(r'^CREATE TABLE `users` \(\n(.*?)^\)', re.IGNORECASE | re.MULTILINE | re.DOTALL)

_ESCAPES = {
    '\\': '\\\\', "'": "\\'", '"': '\\"', '\0': '\\0',
    '\n': '\\n', '\r': '\\r', '\x1a': '\\Z',
}


def sql_literal(value):
    """Encode a value from a pymysql row as a MySQL literal."""
    if value is None:
        return 'NULL'
    if isinstance(value, bool):
        return '1' if value else '0'
    if isinstance(value, (int, float, Decimal)):
        return str(value)
    if isinstance(value, (bytes, bytearray, memoryview)):
        data = bytes(value)
        return "X'" + data.hex() + "'" if data else "''"
    if isinstance(value, datetime):
        return "'" + value.isoformat(sep=' ') + "'"
    if isinstance(value, (date, time)):
        return "'" + value.isoformat() + "'"
    if isinstance(value, timedelta):
        total = int(value.total_seconds())
        sign = '-' if total < 0 else ''
        total = abs(total)
        return f"'{sign}{total // 3600:02d}:{total % 3600 // 60:02d}:{total % 60:02d}'"
    return "'" + ''.join(_ESCAPES.get(ch, ch) for ch in str(value)) + "'"


def insert_statement(table, columns, row):
    """One INSERT with explicit column names, safe for any value."""
    column_list = ', '.join(f'`{column}`' for column in columns)
    return f"INSERT INTO `{table}` ({column_list}) VALUES ({', '.join(sql_literal(v) for v in row)});"


def split_sql_statements(sql):
    """Split a dump into statements without altering text inside literals.

    Understands '...', "..." and `...` quoting, backslash escapes and doubled
    quotes inside literals, and ``-- ``/``#``/``/* */`` comments outside them.
    A trailing statement without ``;`` is returned without one.
    """
    statements, buf = [], []
    i, n, quote = 0, len(sql), None
    while i < n:
        ch = sql[i]
        if quote:
            buf.append(ch)
            if ch == '\\' and quote != '`' and i + 1 < n:
                buf.append(sql[i + 1])
                i += 2
                continue
            if ch == quote:
                if i + 1 < n and sql[i + 1] == quote:  # doubled quote
                    buf.append(sql[i + 1])
                    i += 2
                    continue
                quote = None
            i += 1
            continue
        if ch in ("'", '"', '`'):
            quote = ch
            buf.append(ch)
        elif ch == '-' and sql.startswith('--', i) and (i + 2 >= n or sql[i + 2] in ' \t\r\n'):
            end = sql.find('\n', i)
            i = n if end == -1 else end
            continue
        elif ch == '#':
            end = sql.find('\n', i)
            i = n if end == -1 else end
            continue
        elif ch == '/' and sql.startswith('/*', i):
            end = sql.find('*/', i + 2)
            i = n if end == -1 else end + 2
            continue
        elif ch == ';':
            statement = ''.join(buf).strip()
            if statement:
                statements.append(statement + ';')
            buf = []
        else:
            buf.append(ch)
        i += 1
    tail = ''.join(buf).strip()
    if tail:
        statements.append(tail)
    return statements


def read_backup_inserts(dump):
    """Return the dump's INSERT statements, ready to execute.

    Legacy positional ``users`` inserts get explicit column names from the
    schema recorded in the dump.
    """
    statements = []
    user_columns = None
    for statement in split_sql_statements(dump):
        if not INSERT_START.match(statement):
            continue
        if not statement.endswith(';'):
            raise ValueError('The backup does not contain complete data statements.')
        if LEGACY_USER_INSERT.match(statement):
            if user_columns is None:
                definition = USER_DEFINITION.search(dump)
                columns = re.findall(r'^\s+`([a-zA-Z0-9_]+)`\s', definition[1], re.MULTILINE) if definition else []
                if not columns:
                    raise ValueError('This backup omits the column names for users.')
                user_columns = ', '.join(f'`{column}`' for column in columns)
            statement = LEGACY_USER_INSERT.sub(rf'\g<1> ({user_columns})\g<2>', statement, count=1)
        statements.append(statement)
    if not statements:
        raise ValueError('The backup does not contain complete data statements.')
    return statements
